import axios from 'axios';

function normalizeBaseUrl(url) {
  const raw = (url || 'http://localhost:5050/api').replace(/\/+$/, '');
  return raw.endsWith('/api') ? raw : `${raw}/api`;
}

const API_BASE_URL = normalizeBaseUrl(process.env.REACT_APP_API_URL);
const DUMMY_BASE_URL = 'https://dummyjson.com/products';

const apiClient = axios.create({
  baseURL: API_BASE_URL,
  timeout: 20000,
  headers: {
    'Content-Type': 'application/json',
  },
});

function mapDummyCategory(category = '') {
  const text = category.toLowerCase();

  if (text.includes('mobile') || text.includes('phone')) {
    return 'smartphones';
  }

  if (text.includes('laptop') || text.includes('gaming') || text.includes('hardware')) {
    return 'laptops';
  }

  if (text.includes('access')) {
    return 'mobile-accessories';
  }

  if (text.includes('smart') || text.includes('watch')) {
    return 'mens-watches';
  }

  return '';
}

function inferCategory(item) {
  const text = `${item.category || ''} ${item.title || ''}`.toLowerCase();

  if (/phone|smartphone|iphone|galaxy|mobile/.test(text)) {
    return 'Mobiles';
  }

  if (/laptop|notebook|macbook|zenbook|matebook/.test(text)) {
    return 'Laptops';
  }

  if (/watch|smart/.test(text)) {
    return 'Smart Devices';
  }

  if (/charger|accessor|case|cable|headphone|earbuds/.test(text)) {
    return 'Accessories';
  }

  if (/gaming|playstation|xbox|controller/.test(text)) {
    return 'Gaming';
  }

  return 'Technology';
}

function normalizeDummyProduct(item) {
  const images = Array.isArray(item.images) ? item.images.filter(Boolean) : [];

  return {
    id: `dummyjson_${item.id}`,
    productId: `dummyjson_${item.id}`,
    externalId: String(item.id),
    source: 'dummyjson',
    title: item.title || 'Untitled Product',
    description: item.description || 'No description available.',
    category: inferCategory(item),
    rawCategory: item.category || 'technology',
    brand: item.brand || 'Tech Brand',
    price: Number(item.price || 0),
    currency: 'USD',
    rating: Number(item.rating || 0),
    reviewCount: Array.isArray(item.reviews) ? item.reviews.length : Math.max(1, Math.round(Number(item.rating || 4) * 12)),
    availability: Number(item.stock || 0) > 0 ? 'In stock' : 'Out of stock',
    stock: Number(item.stock || 0),
    image: images[0] || item.thumbnail || '',
    images: images.length ? images : [item.thumbnail].filter(Boolean),
    discountPercentage: Number(item.discountPercentage || 0),
    specifications: {
      Brand: item.brand || 'Tech Brand',
      Category: item.category || 'Technology',
      SKU: item.sku || `TS-${item.id}`,
      Stock: item.stock,
      Warranty: item.warrantyInformation || 'Standard warranty',
      Shipping: item.shippingInformation || 'Standard shipping',
      ReturnPolicy: item.returnPolicy || 'Return policy available',
      Weight: item.weight,
      Dimensions: item.dimensions ? `${item.dimensions.width} × ${item.dimensions.height} × ${item.dimensions.depth}` : '',
    },
    reviews: Array.isArray(item.reviews) ? item.reviews : [],
    productUrl: '',
    sourcePayload: item,
  };
}

function sortProducts(products, sort = 'relevance') {
  const sorted = [...products];

  if (sort === 'price-low') {
    sorted.sort((a, b) => (a.price || 0) - (b.price || 0));
  }

  if (sort === 'price-high') {
    sorted.sort((a, b) => (b.price || 0) - (a.price || 0));
  }

  if (sort === 'rating') {
    sorted.sort((a, b) => (b.rating || 0) - (a.rating || 0));
  }

  if (sort === 'reviews') {
    sorted.sort((a, b) => (b.reviewCount || 0) - (a.reviewCount || 0));
  }

  return sorted;
}

async function directDummySearch(params = {}) {
  const q = params.q || params.search || 'laptop';
  const limit = Number(params.limit || 24);
  const categorySlug = params.category && params.category !== 'all' ? mapDummyCategory(params.category) : '';

  const url = categorySlug
    ? `${DUMMY_BASE_URL}/category/${encodeURIComponent(categorySlug)}?limit=${limit}`
    : `${DUMMY_BASE_URL}/search?q=${encodeURIComponent(q)}&limit=${limit}`;

  let response = await axios.get(url, {
    timeout: 15000,
  });

  let products = Array.isArray(response.data.products) ? response.data.products : [];

  if (products.length === 0) {
    response = await axios.get(`${DUMMY_BASE_URL}/category/laptops?limit=${limit}`, {
      timeout: 15000,
    });

    products = Array.isArray(response.data.products) ? response.data.products : [];
  }

  let normalized = products.map(normalizeDummyProduct);

  if (params.brand && params.brand !== 'all') {
    normalized = normalized.filter((product) => product.brand.toLowerCase().includes(String(params.brand).toLowerCase()));
  }

  if (params.minPrice) {
    normalized = normalized.filter((product) => product.price >= Number(params.minPrice));
  }

  if (params.maxPrice) {
    normalized = normalized.filter((product) => product.price <= Number(params.maxPrice));
  }

  normalized = sortProducts(normalized, params.sort).slice(0, limit);

  return {
    success: true,
    query: q,
    count: normalized.length,
    products: normalized,
    providersUsed: ['dummyjson-direct'],
    cache: 'direct-dummyjson',
    notice: 'Loaded directly from DummyJSON fallback because the backend request was unavailable.',
  };
}

async function directDummyProduct(productId) {
  const id = String(productId)
    .replace('dummyjson_', '')
    .replace(/[^0-9]/g, '');

  const { data } = await axios.get(`${DUMMY_BASE_URL}/${id}`, {
    timeout: 15000,
  });

  return {
    success: true,
    product: normalizeDummyProduct(data),
  };
}

export const productApi = {
  searchProducts: async (params = {}) => {
    const safeParams = {
      q: params.q || params.search || 'laptop',
      category: params.category || 'all',
      brand: params.brand || 'all',
      minPrice: params.minPrice || '',
      maxPrice: params.maxPrice || '',
      sort: params.sort || 'relevance',
      limit: params.limit || 24,
    };

    try {
      const { data } = await apiClient.get('/products/search', {
        params: safeParams,
      });

      return data;
    } catch (error) {
      console.warn('Backend product search failed. Using DummyJSON direct fallback.', error.message);
      return directDummySearch(safeParams);
    }
  },

  getProduct: async (productId) => {
    try {
      const { data } = await apiClient.get(`/products/${encodeURIComponent(productId)}`);
      return data;
    } catch (error) {
      console.warn('Backend product detail failed. Using DummyJSON direct fallback.', error.message);
      return directDummyProduct(productId);
    }
  },

  getTrending: async (limit = 12) => {
    try {
      const { data } = await apiClient.get('/products/trending', {
        params: {
          limit,
        },
      });

      return data;
    } catch {
      return directDummySearch({
        q: 'laptop',
        limit,
        sort: 'rating',
      });
    }
  },

  getSuggestions: async (q = '') => {
    try {
      const { data } = await apiClient.get('/products/suggestions', {
        params: {
          q,
        },
      });

      return data;
    } catch {
      const defaults = [
        'iphone',
        'laptop',
        'smartphone',
        'gaming laptop',
        'headphones',
        'smart watch',
      ];

      return {
        success: true,
        suggestions: defaults.filter((item) => !q || item.includes(String(q).toLowerCase())),
      };
    }
  },

  getCategories: async () => {
    try {
      const { data } = await apiClient.get('/products/categories');
      return data;
    } catch {
      return {
        success: true,
        categories: [
          {
            name: 'Mobiles',
            icon: '📱',
            count: 0,
          },
          {
            name: 'Laptops',
            icon: '💻',
            count: 0,
          },
          {
            name: 'Accessories',
            icon: '🔌',
            count: 0,
          },
          {
            name: 'Gaming',
            icon: '🎮',
            count: 0,
          },
          {
            name: 'Smart Devices',
            icon: '⌚',
            count: 0,
          },
          {
            name: 'Computer Hardware',
            icon: '🧩',
            count: 0,
          },
        ],
      };
    }
  },

  getBrands: async (q = '') => {
    try {
      const { data } = await apiClient.get('/products/brands', {
        params: {
          q,
        },
      });

      return data;
    } catch {
      return {
        success: true,
        brands: [
          'Apple',
          'Samsung',
          'Huawei',
          'Oppo',
          'Asus',
          'Lenovo',
          'Dell',
          'HP',
        ].filter((brand) => !q || brand.toLowerCase().includes(q.toLowerCase())),
      };
    }
  },

  getRecommendations: async (payload = {}) => {
    try {
      const { data } = await apiClient.post('/products/recommendations', payload);
      return data;
    } catch {
      const fallback = await directDummySearch({
        q: payload.query || payload.usage || 'laptop',
        sort: 'rating',
        limit: 8,
      });

      return {
        ...fallback,
        source: 'dummyjson-fallback',
      };
    }
  },

  getProviderStatus: async () => {
    try {
      const { data } = await apiClient.get('/products/providers');
      return data;
    } catch {
      return {
        success: true,
        providers: {
          dummyjson: true,
          backend: false,
        },
      };
    }
  },
};

export const aiApi = {
  chat: async (message, products = []) => {
    try {
      const { data } = await apiClient.post('/ai/chat', {
        message,
        products,
      });

      return data;
    } catch {
      return {
        reply: 'I can help you find products, compare specifications, track orders, and choose the best technology item for your budget.',
      };
    }
  },

  suggest: async (query) => ({
    suggestions: [
      'laptop',
      'smartphone',
      'gaming laptop',
      'headphones',
    ].filter((item) => item.includes(String(query || '').toLowerCase())),
  }),

  sentiment: async (reviews = []) => ({
    success: true,
    sentiment: {
      positive: 78,
      neutral: 15,
      negative: 7,
    },
    reviews,
  }),
};

export default apiClient;
